-- name: CreateUser :one
-- Returns no row when the email is taken (no enumeration in register).
INSERT INTO users (id, email, password_hash, roles, created_at, updated_at)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (email) DO NOTHING
RETURNING *;

-- name: GetUser :one
SELECT * FROM users WHERE id = $1;

-- name: GetUserByEmail :one
SELECT * FROM users WHERE email = $1;

-- name: RecordLoginFailure :one
UPDATE users SET failed_logins = failed_logins + 1, updated_at = sqlc.arg('now')::timestamptz
WHERE id = sqlc.arg('id')
RETURNING failed_logins;

-- name: LockUser :exec
UPDATE users SET locked_until = sqlc.arg('until')::timestamptz WHERE id = sqlc.arg('id');

-- name: RecordLoginSuccess :exec
UPDATE users SET failed_logins = 0, locked_until = NULL WHERE id = $1;

-- name: UpdatePasswordHash :exec
UPDATE users SET password_hash = sqlc.arg('password_hash'), failed_logins = 0, locked_until = NULL,
    updated_at = sqlc.arg('now')::timestamptz
WHERE id = sqlc.arg('id');

-- name: MarkEmailVerified :exec
UPDATE users SET email_verified_at = sqlc.arg('now')::timestamptz, updated_at = sqlc.arg('now')::timestamptz
WHERE id = sqlc.arg('id') AND email_verified_at IS NULL;

-- name: GrantRole :exec
UPDATE users SET roles = array_append(roles, sqlc.arg('role')::text)
WHERE id = sqlc.arg('id') AND NOT (sqlc.arg('role')::text = ANY(roles));

-- name: CreateAuthToken :exec
INSERT INTO auth_tokens (token_hash, user_id, kind, expires_at, created_at)
VALUES ($1, $2, $3, $4, $5);

-- name: ConsumeAuthToken :one
-- Single use: only an unused, unexpired token is consumed, atomically.
UPDATE auth_tokens SET used_at = sqlc.arg('now')::timestamptz
WHERE token_hash = sqlc.arg('token_hash') AND kind = sqlc.arg('kind')
  AND used_at IS NULL AND expires_at > sqlc.arg('now')::timestamptz
RETURNING user_id;
